window.products.push({"id":739786,"name":"Honey Bee Bees Beehive Colony - Vinyl Decal Set for Kitchen Mixers - Copper","category":"homeandappliances","retail price":9.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61aUku0-13L._AC_SL1024_.jpg","description":"Please Note: Mixer Not Included This decal set is made from professional quality long-lasting vinyl. Kit includes decals for top and both sides of your mixer. Be sure to thoroughly clean your mixer before applying your decals to ensure proper application. Grease and dirt may prevent decals from sticking. Once decals are applied use mild cleaners such as dish soap to clean when necessary. Avoid harsh cleaners and harsh scrubbing of small pieces. Can also be applied to smooth surfaces such as glass, metal, and plastic.  For mixers, juicers and more!  Easy to follow Instructions included in package. 100% satisfaction guarantee. Please contact us if you have any issues with the product. If you have any questions or concerns please send us a message. We'll be happy to provide answers.","images":["https://m.media-amazon.com/images/I/61aUku0-13L._AC_SL1024_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Applicable Pun","source_asin":"B01CF6MR2K","category_path":"Home & Kitchen"},"sku":"BM-739786","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01CF6MR2K","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01CF6MR2K","price_pending":true,"merchant_ready":false});
